function Choice({value,onChange,items,label,id}:{value:string;onChange:(value:string)=>void;items:{value:string;label:string}[];label:string;id?:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger id={id} className="choice" aria-label={label}><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{items.map(i=><SelectItem key={i.value} value={i.value}>{i.label}</SelectItem>)}</SelectContent></Select>;}
function GoalIcon({goal}:{goal:Pick<Goal,"name">}){const icons={gamepad:Gamepad2,car:Car,bike:Bike,phone:Smartphone,laptop:Laptop,monitor:Monitor,tv:Tv,camera:Camera,headphones:Headphones,home:Home,plane:Plane,ticket:Ticket,shirt:Shirt,gift:Gift,book:BookOpen,dumbbell:Dumbbell,watch:Watch,target:Target};const Icon=icons[symbolForGoal(goal)];return <Icon aria-hidden size={30} strokeWidth={1.5}/>;}
const entryLabel=(e:Entry)=>({income:"Income recorded",save:"Added from existing savings",allocate:"Reserved from recorded income",release:"Released to available balance",purchase:"Purchase recorded",withdraw:"Removed from available balance"})[e.kind];
function EntryRow({entry,format,edit,remove,busy,isPurchasePart}:{entry:Entry;format:(cents:number)=>string;edit:()=>void;remove:()=>void;busy:boolean;isPurchasePart:boolean}){const positive=entry.kind==="income"||entry.kind==="save"||entry.kind==="allocate";return <div className="entry"><span className={`entry-icon ${positive?"positive":""}`}>{entry.kind==="purchase"?<Check size={18}/>:positive?<ArrowDownLeft size={18}/>:<ArrowUpRight size={18}/>}</span><div className="entry-text"><strong>{entry.goalName||entry.note||entryLabel(entry)}</strong><span>{entryLabel(entry)}{entry.conversion?` · ${entry.conversion.originalAmount} ${entry.conversion.currency}`:""}{entry.note&&entry.goalName?` · ${entry.note}`:""}</span></div><div className="entry-amount"><strong>{format(entry.amountCents)}</strong><span>{dateLabel(entry.date)}</span></div><DropdownMenu><DropdownMenuTrigger asChild><button className="icon-button entry-menu" aria-label={`Options for ${entryLabel(entry)} ${format(entry.amountCents)} on ${dateLabel(entry.date)}`} disabled={busy}><MoreHorizontal size={18}/></button></DropdownMenuTrigger><DropdownMenuContent className="gullak-menu" align="end"><DropdownMenuItem onSelect={edit}>{isPurchasePart?"Edit Purchase":"Edit Entry"}</DropdownMenuItem><DropdownMenuItem onSelect={remove} className="danger-menu-item">{isPurchasePart?"Delete Purchase":"Delete Entry"}</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div>;}

