 useEffect(()=>{void refresh(true);const onFocus=()=>{if(document.visibilityState==="visible"&&!saving.current)void refresh();};const onStorage=(e:StorageEvent)=>{if(storageMode==="guest"&&e.key===GUEST_KEY)void refresh();};window.addEventListener("focus",onFocus);document.addEventListener("visibilitychange",onFocus);window.addEventListener("storage",onStorage);return()=>{window.removeEventListener("focus",onFocus);document.removeEventListener("visibilitychange",onFocus);window.removeEventListener("storage",onStorage);};},[refresh,storageMode]);
