 const downloadBackup=()=>{if(!snapshot)return;const file=new Blob([JSON.stringify({app:"gullak",exportedAt:new Date().toISOString(),state:snapshot.state},null,2)],{type:"application/json"});const url=URL.createObjectURL(file),a=document.createElement("a");a.href=url;a.download=`gullak-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast.success("Backup downloaded to your device");};
