 const readCsv=async(file?:File)=>{if(!file)return;setFormError("");try{if(file.size>2000000)throw new Error("Choose a CSV smaller than 2 MB.");const rows=parseCsv((await file.text()).replace(/^\uFEFF/,""));if(rows.length<2||rows.length>5001||rows[0].length<3)throw new Error("Use a CSV with a header row, date, description, and amount, and up to 5,000 transactions.");setCsv(rows);setCsvName(file.name);const h=rows[0].map(x=>x.toLowerCase());const idx=(terms:string[],fallback:number)=>{const i=h.findIndex(x=>terms.some(t=>x.includes(t)));return String(i<0?fallback:i);};setMapping({date:idx(["date"],0),description:idx(["description","memo","name"],1),amount:idx(["amount","credit"],2),sign:"positive"});setCandidates([]);setSelected([]);setCsvInfo("");}catch(e){setFormError((e as Error).message);}};
