 useEffect(()=>{if(storageMode==="guest")return;const ctx=(document as Document&{modelContext?:{registerTool:(tool:unknown,options:unknown)=>Promise<void>|void}}).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();const tool={name:"read_gullaks",title:"Read my gullaks",description:"Read the currently loaded goals and balances without changing anything.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input:unknown)=>{if(!input||typeof input!=="object"||Object.keys(input).length)throw new Error("No parameters are accepted.");const s=current.current;if(!s)throw new Error("Your gullaks have not loaded yet.");return {unallocatedCents:available(s.state),reservedCents:reserved(s.state),goalTargetCents:goalTotals(s.state).targetCents,earnedIncomeCents:earnedIncome(s.state),lossCents:-losses(s.state),goals:s.state.goals.map(g=>({id:g.id,name:g.name,targetCents:g.targetCents,savedCents:balance(s.state,g.id),status:g.status,draft:g.draft}))};}};try{void Promise.resolve(ctx.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}return()=>lifecycle.abort();},[storageMode]);
 const splitTotal=split.reduce((sum,a)=>{if(!a.amount.trim())return sum;try{return sum+convertInput(a.amount,fields.currency,fx).cents;}catch{return Number.NaN;}},0);
 const modalTitle=mode==="entry"?"Edit History Entry":mode==="reset"?"Reset Dashboard":mode==="close"?`Delete ${goal?.name??"goal"}?`:mode==="goal"?(goal?(goal.draft?"Set Goal":"Edit Goal"):"Create a Goal"):mode==="income"?"Record Income":mode==="contribute"?(goal?`Add to ${goal.name}`:"Add Money"):mode==="release"?"Release Money":mode==="purchase"?"Confirm Purchase":mode==="withdraw"?"Remove Available Money":mode==="split"?"Allocate Money":mode==="import"?"Import Statement":"Settings & Backups";
